// Procesar acción capturada y preparar datos para MCP
const actionData = $json;

// Información detallada de la acción
const processedAction = {
  // Datos de la acción
  actionType: actionData.action || actionData.type || 'unknown',
  element: actionData.element || '',
  value: actionData.value || '',
  selector: actionData.selector || '',

  // Contexto de página
  pageUrl: actionData.url || '',
  pageTitle: actionData.title || '',

  // Metadatos
  sessionId: actionData.sessionId || `session_${Date.now()}`,
  timestamp: actionData.timestamp || new Date().toISOString(),
  userAgent: actionData.userAgent || ''
};

// Respuesta con información detallada
const response = {
  success: true,
  message: `🎯 ACCIÓN CAPTURADA: ${processedAction.actionType.toUpperCase()}`,

  // Detalles del paso
  actionDetails: {
    step: processedAction.actionType,
    target: processedAction.element,
    value: processedAction.value,
    page: processedAction.pageTitle,
    url: processedAction.pageUrl,
    timestamp: processedAction.timestamp
  },

  // Información de sesión
  session: {
    id: processedAction.sessionId,
    stepCount: 1,
    readyForMCP: true
  },

  // Datos preparados para MCP
  mcpData: {
    context: `User action on ${processedAction.pageTitle}`,
    action: processedAction.actionType,
    element: processedAction.element,
    value: processedAction.value,
    timestamp: processedAction.timestamp
  }
};

console.log('🔄 Acción procesada para MCP:', processedAction);

return [{json: response}];

// Preparar datos de sesión para generación de tests con MCP
const requestData = $json;

// Compilar información de la sesión
const sessionData = {
  sessionId: requestData.sessionId || 'unknown',
  actions: requestData.actions || [],
  pageTitle: requestData.pageTitle || 'Unknown Page',
  pageUrl: requestData.pageUrl || '',
  totalActions: (requestData.actions || []).length
};

// Crear prompt estructurado para MCP
const mcpPrompt = {
  task: 'generate_test_automation_code',
  context: {
    application: sessionData.pageTitle,
    url: sessionData.pageUrl,
    userActions: sessionData.actions,
    sessionId: sessionData.sessionId
  },
  requirements: {
    frameworks: ['selenium', 'playwright', 'cypress'],
    language: 'javascript',
    pattern: 'page_object_model',
    assertions: true,
    waits: true,
    error_handling: true
  },
  output_format: 'structured_json'
};

// Respuesta con datos preparados para MCP
const response = {
  success: true,
  message: `🚀 Preparando generación con MCP para ${sessionData.totalActions} acciones`,
  sessionInfo: sessionData,
  mcpPrompt: mcpPrompt,
  timestamp: new Date().toISOString()
};

console.log('🔧 Datos preparados para MCP:', mcpPrompt);

return [{json: response}];

// Simular respuesta MCP (hasta que configuremos la conexión real)
const mcpData = $json;

// Generar código de test mock usando los datos MCP
const generatedCode = {
  selenium: {
    language: 'javascript',
    code: `
// Selenium WebDriver Test
const { Builder, By, until } = require('selenium-webdriver');

describe('${mcpData.sessionInfo.pageTitle} Test', () => {
  let driver;

  beforeEach(async () => {
    driver = await new Builder().forBrowser('chrome').build();
  });

  afterEach(async () => {
    await driver.quit();
  });

  it('should execute recorded user actions', async () => {
    await driver.get('${mcpData.sessionInfo.pageUrl}');

    // Acciones generadas basadas en MCP:
${(mcpData.sessionInfo.actions || []).map((action, i) => 
  `    // Paso ${i + 1}: ${action.type || 'action'} en ${action.element || 'elemento'}`
).join('\n')}

    // Verificaciones
    const title = await driver.getTitle();
    expect(title).toContain('${mcpData.sessionInfo.pageTitle}');
  });
});
`
  },

  playwright: {
    language: 'javascript',
    code: `
// Playwright Test
const { test, expect } = require('@playwright/test');

test.describe('${mcpData.sessionInfo.pageTitle} Test', () => {
  test('should execute recorded actions', async ({ page }) => {
    await page.goto('${mcpData.sessionInfo.pageUrl}');

    // Acciones MCP generadas:
${(mcpData.sessionInfo.actions || []).map((action, i) => 
  `    // Paso ${i + 1}: ${action.type || 'action'} en ${action.element || 'elemento'}`
).join('\n')}

    // Verificaciones
    await expect(page).toHaveTitle(/${mcpData.sessionInfo.pageTitle}/);
  });
});
`
  }
};

// Respuesta final con código generado
const finalResponse = {
  success: true,
  message: '✅ Tests generados exitosamente con MCP',
  sessionId: mcpData.sessionInfo.sessionId,
  generatedAt: new Date().toISOString(),

  // Código generado
  testCode: generatedCode,

  // Metadatos
  metadata: {
    actionCount: mcpData.sessionInfo.totalActions,
    frameworks: ['selenium', 'playwright'],
    mcpProcessed: true,
    generationTime: new Date().toISOString()
  },

  // Información de la sesión
  session: mcpData.sessionInfo
};

console.log('✅ Tests generados con MCP para sesión:', mcpData.sessionInfo.sessionId);

return [{json: finalResponse}];
